// ──────────────────────────── tests ──────────────────────────────────────

Test("joins the parts", () =>
    Eq(JoinNonEmpty(", ", "a", "b", "c"), "a, b, c"));

Test("skips null, empty and whitespace parts", () =>
    Eq(JoinNonEmpty(", ", "a", null, "", "  ", "b"), "a, b"));

Test("one part has no separator", () => Eq(JoinNonEmpty(", ", "solo"), "solo"));

Test("nothing to join is an empty string", () =>
{
    Eq(JoinNonEmpty(", "), "");
    Eq(JoinNonEmpty(", ", null, "  "), "");
});

Test("parses a key=value pair", () =>
{
    var pair = ParsePair("host=localhost");

    Eq(pair?.Key, "host");
    Eq(pair?.Value, "localhost");
});

Test("trims around the separator", () =>
{
    var pair = ParsePair("  host  =  localhost  ");

    Eq(pair?.Key, "host");
    Eq(pair?.Value, "localhost");
});

Test("a value may itself contain =", () =>
    Eq(ParsePair("url=http://x/?a=b")?.Value, "http://x/?a=b"));

Test("a malformed line is null, not an exception", () =>
{
    Eq(ParsePair("no separator here"), null);
    Eq(ParsePair(""), null);
    Eq(ParsePair("=novalue"), null);      // empty key
});

Test("counts words over a span", () =>
{
    Eq(CountWords("one two three"), 3);
    Eq(CountWords("  padded   out  "), 2);
    Eq(CountWords("solo"), 1);
});

Test("an empty or blank span has no words", () =>
{
    Eq(CountWords(""), 0);
    Eq(CountWords("   "), 0);
});

Test("identifier comparison ignores case", () =>
{
    Ok(SameIdentifier("Host", "host"));
    Ok(SameIdentifier("HOST", "host"));
    Ok(!SameIdentifier("host", "hostname"));
});

Test("comparison does not depend on the machine's culture", () =>
{
    // The Turkish-I problem: a culture-sensitive comparison can decide
    // "I" and "i" are different letters. An ordinal one cannot.
    var previous = System.Globalization.CultureInfo.CurrentCulture;
    System.Globalization.CultureInfo.CurrentCulture =
        new System.Globalization.CultureInfo("tr-TR");
    try
    {
        Ok(SameIdentifier("ID", "id"));
    }
    finally
    {
        System.Globalization.CultureInfo.CurrentCulture = previous;
    }
});

// ──────────────────────────── tests ──────────────────────────────────────

Test("a valid SKU matches", () => Ok(IsSku("ABC-1234")));

Test("anchors reject a SKU embedded in other text", () =>
{
    // Without ^ and $ these would all pass, because the pattern matches
    // SOMEWHERE inside them.
    Ok(!IsSku("xABC-1234"));
    Ok(!IsSku("ABC-1234x"));
    Ok(!IsSku("say ABC-1234 please"));
});

Test("the shape is enforced exactly", () =>
{
    Ok(!IsSku("AB-1234"));      // too few letters
    Ok(!IsSku("ABC-123"));      // too few digits
    Ok(!IsSku("abc-1234"));     // wrong case
    Ok(!IsSku(""));
});

Test("named groups extract the date parts", () =>
{
    var parsed = ParseDate("2026-03-01");

    Eq(parsed?.Year, 2026);
    Eq(parsed?.Month, 3);
    Eq(parsed?.Day, 1);
});

Test("a non-date is null", () =>
{
    Eq(ParseDate("not a date"), null);
    Eq(ParseDate("2026-3-1"), null);     // not zero-padded
});

Test("finds every hashtag", () =>
    Eq(Hashtags("hello #csharp and #dotnet"), new[] { "csharp", "dotnet" }));

Test("hashtags are deduplicated, keeping first-seen order", () =>
    Eq(Hashtags("#b #a #b #c"), new[] { "b", "a", "c" }));

Test("text with no hashtags gives an empty list", () =>
    Eq(Hashtags("nothing here"), new List<string>()));

Test("a lone # is not a hashtag", () =>
    Eq(Hashtags("# #ok"), new[] { "ok" }));

Test("Squash collapses whitespace runs", () =>
{
    Eq(Squash("a   b\t\tc"), "a b c");
    Eq(Squash("  padded  "), "padded");
    Eq(Squash("already fine"), "already fine");
});

Test("Squash handles empty and blank input", () =>
{
    Eq(Squash(""), "");
    Eq(Squash("   "), "");
});

Test("a compiled pattern is reused, not re-parsed per call", () =>
{
    // Correctness check on the same instance being used repeatedly.
    for (var i = 0; i < 1000; i++) Ok(IsSku("ABC-1234"));
});

// ──────────────────────────── tests ──────────────────────────────────────

var german = CultureInfo.GetCultureInfo("de-DE");
var american = CultureInfo.GetCultureInfo("en-US");

Test("machine format is a plain dotted number", () =>
{
    Eq(ForMachine(1234.5m), "1234.50");
    Eq(ForMachine(0.5m), "0.50");
    Eq(ForMachine(-2m), "-2.00");
});

Test("machine format does not change with the culture", () =>
{
    // The whole point. Run this on a German machine and it must not become
    // "1234,50" — something is going to parse it back.
    var previous = CultureInfo.CurrentCulture;
    CultureInfo.CurrentCulture = german;

    try
    {
        Eq(ForMachine(1234.5m), "1234.50");
    }
    finally
    {
        CultureInfo.CurrentCulture = previous;
    }
});

Test("human format follows the culture it is given", () =>
{
    Ok(ForPerson(1234.5m, american).Contains('$'), ForPerson(1234.5m, american));
    Ok(ForPerson(1234.5m, german).Contains('€'), ForPerson(1234.5m, german));
});

Test("machine output round-trips through the parser", () =>
{
    Eq(ParseMachine(ForMachine(1234.5m)), 1234.50m);
    Eq(ParseMachine(ForMachine(-0.05m)), -0.05m);
});

Test("parsing is invariant too, so a comma-decimal is NOT accepted", () =>
{
    // "1234,50" is a valid German number and invalid invariant input.
    // Accepting it silently would turn 1234.50 into 123450 — so the parse
    // has to refuse group separators as well as choose the culture.
    Eq(ParseMachine("1234,50"), null);
    Eq(ParseMachine("nonsense"), null);
    Eq(ParseMachine(""), null);
});

Test("the ISO date is fixed, whatever the culture", () =>
{
    var previous = CultureInfo.CurrentCulture;
    CultureInfo.CurrentCulture = german;

    try
    {
        Eq(IsoDate(new DateOnly(2026, 9, 2)), "2026-09-02");
    }
    finally
    {
        CultureInfo.CurrentCulture = previous;
    }
});

Test("the round-trip format keeps the offset", () =>
{
    var moment = new DateTimeOffset(2026, 9, 2, 13, 30, 0, TimeSpan.FromHours(2));
    var text = RoundTrip(moment);

    Eq(DateTimeOffset.Parse(text, CultureInfo.InvariantCulture), moment);
    Ok(text.Contains("+02:00"), text);
});

Test("a round-tripped moment survives being parsed back exactly", () =>
{
    var moment = DateTimeOffset.UtcNow;
    var parsed = DateTimeOffset.Parse(RoundTrip(moment), CultureInfo.InvariantCulture);

    // "O" keeps all seven fractional digits. A format that drops them —
    // "yyyy-MM-dd HH:mm:ss" — loses up to a second, and the equality test
    // that used to pass starts failing at random.
    Eq(parsed, moment);
});

// ──────────────────────────── tests ──────────────────────────────────────

Test("fields are split and trimmed", () =>
    Eq(Fields("a, b ,c"), new[] { "a", "b", "c" }));

Test("blank fields disappear", () =>
{
    // " " is trimmed to "" and THEN removed — which only works because the
    // two options combine in that order.
    Eq(Fields("a, ,b"), new[] { "a", "b" });
    Eq(Fields("a,,b"), new[] { "a", "b" });
    Eq(Fields(""), Array.Empty<string>());
});

Test("Sentence joins without a trailing separator", () =>
{
    Eq(Sentence(["a", "b", "c"]), "a, b, c");
    Eq(Sentence(["a"]), "a");
    Eq(Sentence([]), "");
});

Test("AndList reads like English", () =>
{
    Eq(AndList(["a", "b", "c"]), "a, b and c");
    Eq(AndList(["a", "b"]), "a and b");
    Eq(AndList(["a"]), "a");
    Eq(AndList([]), "");
});

Test("a plain CSV line splits as you would expect", () =>
    Eq(CsvFields("a,b,c"), new[] { "a", "b", "c" }));

Test("a quoted field may contain a comma", () =>
{
    // This is why `line.Split(',')` is wrong for CSV, and why the bug only
    // appears once a customer is called "Smith, Jane".
    Eq(CsvFields("\"Smith, Jane\",30,london"),
       new[] { "Smith, Jane", "30", "london" });
});

Test("a doubled quote inside a quoted field is a literal quote", () =>
    Eq(CsvFields("\"say \"\"hi\"\"\",x"), new[] { "say \"hi\"", "x" }));

Test("empty fields are preserved in CSV, unlike Fields", () =>
{
    // Different job, different rule: in a CSV an empty field is a column
    // with no value, and dropping it would shift every later column.
    Eq(CsvFields("a,,c"), new[] { "a", "", "c" });
    Eq(CsvFields(",a"), new[] { "", "a" });
});

Test("a quoted empty field survives", () =>
    Eq(CsvFields("a,\"\",c"), new[] { "a", "", "c" }));

// ──────────────────────────── tests ──────────────────────────────────────

Test("identifiers compare case-insensitively", () =>
{
    Ok(SameIdentifier("Content-Type", "content-type"));
    Ok(SameIdentifier("FILE", "file"));
    Ok(!SameIdentifier("file", "files"));
});

Test("...and survive a Turkish machine", () =>
{
    // ToLower() here would give "fıle" and the comparison would fail. This
    // is a real bug class, and it has shipped in real authentication code.
    var previous = CultureInfo.CurrentCulture;
    CultureInfo.CurrentCulture = CultureInfo.GetCultureInfo("tr-TR");

    try
    {
        Ok(SameIdentifier("FILE", "file"), "the Turkish I broke it");
        Ok(HasExtension("REPORT.PDF", ".pdf"));
    }
    finally
    {
        CultureInfo.CurrentCulture = previous;
    }
});

Test("extensions match regardless of case", () =>
{
    Ok(HasExtension("report.PDF", ".pdf"));
    Ok(HasExtension("report.pdf", ".PDF"));
    Ok(!HasExtension("report.pdf.exe", ".pdf"), "it must be the END of the name");
});

Test("FindOrdinal finds and reports -1", () =>
{
    Eq(FindOrdinal("Hello World", "world"), 6);
    Eq(FindOrdinal("Hello World", "HELLO"), 0);
    Eq(FindOrdinal("Hello", "z"), -1);
});

Test("an empty needle is found at 0", () =>
    Eq(FindOrdinal("Hello", ""), 0));

Test("people-sorting is linguistic", () =>
{
    // Ordinal would put every capital letter before every lowercase one,
    // because that is the order the code points happen to be in.
    Eq(SortedForPeople(["banana", "Apple", "cherry"], CultureInfo.InvariantCulture),
       new[] { "Apple", "banana", "cherry" });
});

Test("machine-sorting is ordinal, and looks wrong to a person", () =>
{
    // "Z" (90) sorts before "a" (97). That is correct for a machine and
    // completely wrong for a name list — which is the whole distinction.
    Eq(SortedForMachines(["a", "Z", "B"]), new[] { "B", "Z", "a" });
});

Test("machine-sorting does not move when the culture does", () =>
{
    var previous = CultureInfo.CurrentCulture;
    CultureInfo.CurrentCulture = CultureInfo.GetCultureInfo("tr-TR");

    try
    {
        Eq(SortedForMachines(["a", "Z", "B"]), new[] { "B", "Z", "a" });
    }
    finally
    {
        CultureInfo.CurrentCulture = previous;
    }
});

// ──────────────────────────── tests ──────────────────────────────────────

Test("a simple title", () =>
    Eq(Slug("Hello World"), "hello-world"));

Test("punctuation becomes a separator", () =>
    Eq(Slug("Hello, World!"), "hello-world"));

Test("runs of rubbish collapse to ONE dash", () =>
    Eq(Slug("Hello   ---  World"), "hello-world"));

Test("no leading or trailing dashes", () =>
{
    Eq(Slug("  Hello World  "), "hello-world");
    Eq(Slug("!!!Hello!!!"), "hello");
});

Test("digits survive", () =>
    Eq(Slug("Part 2 of 3"), "part-2-of-3"));

Test("accents are stripped to their base letter", () =>
{
    Eq(Slug("Café Life"), "cafe-life");
    Eq(Slug("Crème Brûlée"), "creme-brulee");
    Eq(Slug("Ångström"), "angstrom");
});

Test("both encodings of the same accent give the same slug", () =>
{
    // "é" as one code point, and as "e" + combining acute. They look
    // identical and are different strings; the slug must not care.
    var composed = "Café";
    var decomposed = "Café";

    Ok(composed != decomposed, "these really are different strings");
    Eq(Slug(composed), Slug(decomposed));
    Eq(Slug(composed), "cafe");
});

Test("case folding is invariant", () =>
{
    var previous = CultureInfo.CurrentCulture;
    CultureInfo.CurrentCulture = CultureInfo.GetCultureInfo("tr-TR");

    try
    {
        // ToLower() on a Turkish machine turns "I" into a dotless "ı",
        // which is not an ASCII letter and would vanish.
        Eq(Slug("TITLE I"), "title-i");
    }
    finally
    {
        CultureInfo.CurrentCulture = previous;
    }
});

Test("an input with nothing usable is empty", () =>
{
    Eq(Slug("!!!"), "");
    Eq(Slug("   "), "");
    Eq(Slug(""), "");
});

Test("non-Latin script is dropped rather than mangled", () =>
{
    // A real slug generator would transliterate. This one keeps ASCII
    // letters and digits only, which is a defensible choice as long as it
    // is a CHOICE — the empty result is what tells you to think about it.
    Eq(Slug("日本語 title"), "title");
});

