// ──────────────────────────── tests ──────────────────────────────────────

Test("fields are split and trimmed", () =>
    Eq(Fields("a, b ,c"), new[] { "a", "b", "c" }));

Test("blank fields disappear", () =>
{
    // " " is trimmed to "" and THEN removed — which only works because the
    // two options combine in that order.
    Eq(Fields("a, ,b"), new[] { "a", "b" });
    Eq(Fields("a,,b"), new[] { "a", "b" });
